/**
 * The measured track record of the Markov BUY/SELL call, quoted next to it: how often that call was right for the
 * asset type at that horizon over the 2021-2025 walk-forward (live settings), against the share of all days that
 * moved the call's way regardless of the model. The data is regenerated by
 * `bun run src/tools/finance/backtest/long-history-skill.ts track-record`.
 */
import type { AssetProfile } from './asset-profile.js';
import { CALL_TRACK_RECORD_DATA } from './call-track-record-data.js';

interface TrackRecordData {
  period: string;
  horizons: number[];
  measuredOn: Record<string, string[]>;
  records: Record<string, { calls: number; hitRate: number; baseRate: number }>;
}

export interface CallTrackRecord {
  assetType: AssetProfile['type'];
  horizon: number;
  /** The measured horizon the record comes from: the nearest one to `horizon`. */
  measuredHorizon: number;
  call: 'BUY' | 'SELL';
  calls: number;
  hitRate: number;
  /** Share of all days, whatever the model said, that moved the call's way. */
  baseRate: number;
  period: string;
  measuredOn: string[];
}

/** Fewer calls than this read as noise ("right 71% of 7 calls"), so they get no record. */
const MIN_CALLS = 30;

/**
 * The record for a call, from the nearest measured horizon; null for HOLD, outside the measured horizons, for an
 * unmeasured asset type, or when fewer than MIN_CALLS such calls were measured.
 */
export function lookupCallTrackRecord(
  assetType: AssetProfile['type'],
  horizon: number,
  call: 'BUY' | 'HOLD' | 'SELL',
  data: TrackRecordData = CALL_TRACK_RECORD_DATA,
): CallTrackRecord | null {
  if (call === 'HOLD') return null;
  const horizons = data.horizons;
  if (horizon < horizons[0] || horizon > horizons[horizons.length - 1]) return null;
  const measuredHorizon = horizons.reduce((best, h) => Math.abs(h - horizon) < Math.abs(best - horizon) ? h : best);
  const record = data.records[`${assetType}|${measuredHorizon}|${call}`];
  if (!record || record.calls < MIN_CALLS) return null;
  return {
    assetType, horizon, measuredHorizon, call, ...record,
    period: data.period, measuredOn: data.measuredOn[assetType] ?? [],
  };
}

export function formatCallTrackRecord(record: CallTrackRecord): string {
  const pct = (x: number) => `${Math.round(100 * x)}%`;
  const moved = record.call === 'BUY' ? 'rose' : 'fell';
  return `📏 Track record (${record.assetType} at ${record.measuredHorizon}d, measured on ${record.measuredOn.join(', ')}, ${record.period}): `
    + `${record.call} calls were right ${pct(record.hitRate)} of ${record.calls.toLocaleString('en-US')} daily calls; `
    + `the price ${moved} on ${pct(record.baseRate)} of all days.`;
}
